import sys

def factor(x):
 d=2
 out=[]
 while d*d<=x:
  if x%d==0:
   c=0
   while x%d==0: x//=d;c+=1
   out.append((d,c))
  d+=1
 if x>1:out.append((x,1))
 return out

def solve(N,A):
 fs={}
 for i,x in enumerate(A):
  for p,a in factor(x): fs.setdefault(p,[0]*len(A))[i]=a
 ans=1
 for p,aa in fs.items():
  L=sum(aa); dp=[0]*(L+1);dp[0]=1
  powers=[1]*(L+1)
  for j in range(1,L+1):powers[j]=powers[j-1]*p%MOD
  upto=0
  for idx,a in enumerate(aa):
   i=idx+1
   nd=[0]*(L+1)
   if a==0:
    for x in range(upto+1):
     if dp[x]: nd[x]=(nd[x]+dp[x]*powers[x])%MOD
   else:
    lowpow=[pow(p,i*k,MOD) for k in range(a+1)]
    for x in range(upto+1):
     v=dp[x]
     if not v:continue
     for step in (-a,a):
      y=x+step
      if y>=0: nd[y]=(nd[y]+v*powers[y])%MOD
      else: nd[0]=(nd[0]+v*lowpow[-y])%MOD
   dp=nd;upto+=a
  ans=ans*sum(dp)%MOD
 return ans

