def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    it=iter(data); n=next(it); q=next(it)
    parent=list(range(n)); sz=[1]*n; left=list(range(n)); right=list(range(n)); col=list(range(1,n+1)); cnt=[0]+[1]*n
    def find(x):
        r=x
        while parent[r]!=r: r=parent[r]
        while parent[x]!=x:
            p=parent[x]; parent[x]=r; x=p
        return r
    def merge(a,b):
        a=find(a); b=find(b)
        if a==b: return a
        if sz[a]<sz[b]: a,b=b,a
        parent[b]=a; sz[a]+=sz[b]
        left[a]=min(left[a],left[b]); right[a]=max(right[a],right[b])
        return a
    out=[]
    for _ in range(q):
        typ=next(it)
        if typ==1:
            x=next(it)-1; c=next(it)
            r=find(x); old=col[r]
            if old==c: continue
            cnt[old]-=sz[r]; cnt[c]+=sz[r]; col[r]=c
            if left[r]>0:
                a=find(left[r]-1)
                if col[a]==c: r=merge(r,a)
            if right[r]<n-1:
                b=find(right[r]+1)
                if col[b]==c: r=merge(r,b)
        else:
            c=next(it); out.append(str(cnt[c]))
    sys.stdout.write('\n'.join(out))

