import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            l,r=sorted((a,b))
            events[r].append((l,i))
        cnt=[0]*(n+1)
        sole=[-1]*(n+1)
        heap=[]
        gains=[0]*len(conflictingPairs)
        total=0
        for r in range(1,n+1):
            for l,i in events[r]:
                if cnt[l]==0:
                    heapq.heappush(heap,-l)
                cnt[l]+=1
                if cnt[l]==1: sole[l]=i
                else: sole[l]=-1
            while heap and cnt[-heap[0]]==0:
                heapq.heappop(heap)
            top=-heap[0] if heap else 0
            total += r-top
            if top and cnt[top]==1:
                idx=sole[top]
                heapq.heappop(heap)
                while heap and cnt[-heap[0]]==0:
                    heapq.heappop(heap)
                second=-heap[0] if heap else 0
                heapq.heappush(heap,-top)
                gains[idx] += top-second
        return total+max(gains)

