        a,b,c=map(int,input().split()); edges[i]=(a-1,b-1,c)
    queries=[]; closed=[False]*M
    for _ in range(Q):
        t,*v=map(int,input().split())
        if t==1:
            i=v[0]-1; closed[i]=True; queries.append((1,i))
        else:
            queries.append((2,v[0]-1,v[1]-1))
    INF=10**30
    d=[[INF]*N for _ in range(N)]
    for i in range(N): d[i][i]=0
    for i,(a,b,c) in enumerate(edges):
        if not closed[i]: d[a][b]=d[b][a]=c
    for k in range(N):
        dk=d[k]
        for i in range(N):
            dik=d[i][k]
            if dik==INF: continue
            di=d[i]
            for j in range(N):
                x=dik+dk[j]
                if x<di[j]: di[j]=x
    ans=[]
    for q in reversed(queries):
        if q[0]==2:
            x,y=q[1:]; ans.append(-1 if d[x][y]==INF else d[x][y])
        else:
            a,b,c=edges[q[1]]
            da=d[a][:]; db=d[b][:]
            for i in range(N):
                di=d[i]
                ia=di[a]; ib=di[b]
                for j in range(N):
                    v1=ia+c+db[j]
                    v2=ib+c+da[j]
                    if v1<di[j]: di[j]=v1
                    if v2<di[j]: di[j]=v2
    print('\n'.join(map(str,reversed(ans))))

