        ok=False
        for k in range(N+1):
            # Insert a value of rank k+1, shifting existing values above it.
            q=tuple(x if x<=k else x+1 for x in p)+(k+1,)
            if lis(q)==A and lis(tuple(-x for x in q))==B:
                ok=True
                break
        if ok:
            ans+=1
    print(ans%M)

