class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        good = [False] * (n + 1)
        for t in range(1, n + 1):
            x = t
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[t] = steps + 1 <= k
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for t in range(1, n + 1):
                    if good[t]:
                        need = t - ones
                        if 0 <= need <= rem:
                            ans = (ans + comb[rem][need]) % MOD
                ones += 1
        return ans % MOD

