import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    seg = []
    for _ in range(m):
        s, t = next(it), next(it)
        seg.append((min(s, t), max(s, t)))
    queries = [(next(it)-1, next(it)-1) for _ in range(q)]

    # A set of requirements is feasible exactly when its intervals form a
    # laminar family (identical intervals are harmless).
    # For each index, record the earliest later interval incompatible with it.
    # The interval endpoints are on a line, so test conflicts by scanning
    # intervals in increasing input order.
    first_bad = [m] * m
    for i in range(m):
        a, b = seg[i]
        for j in range(i + 1, m):
            c, d = seg[j]
            if (a, b) == (c, d):
                continue
            # Intersections are permitted only for strict containment.
            if max(a, c) <= min(b, d):
                if not (a < c and d < b) and not (c < a and b < d):
                    first_bad[i] = j
                    break
    out = []
    for l, r in queries:
        ok = True
        for i in range(l, r + 1):
            if first_bad[i] <= r:
                ok = False
                break
        out.append('Yes' if ok else 'No')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

