import sys
from collections import deque

def main():
    data=sys.stdin.buffer.read().split()
    if not data: return
    n=int(data[0]); g=[x.decode() for x in data[1:1+n]]
    inf=10**9
    dist=[[inf]*n for _ in range(n)]
    unvis=[(1<<n)-1 for _ in range(n)]
    q=deque()
    for i in range(n):
        dist[i][i]=0; unvis[i]&=~(1<<i); q.append((i,i))
    for i in range(n):
        for j,c in enumerate(g[i]):
            if c!='-' and dist[i][j]>1:
                dist[i][j]=1; unvis[i]&=~(1<<j); q.append((i,j))
    # incoming groups for each middle vertex
    inc=[{} for _ in range(n)]
    out=[{} for _ in range(n)]
    for i in range(n):
        for j,c in enumerate(g[i]):
            if c!='-':
                out[i][c]=out[i].get(c,0)|(1<<j)
                inc[j].setdefault(c,[]).append(i)
    while q:
        u,v=q.popleft(); nd=dist[u][v]+2
        for c,sources in inc[u].items():
            mask=out[v].get(c,0)
            if not mask: continue
            for a in sources:
                bits=mask & unvis[a]
                while bits:
                    bit=bits & -bits; bits-=bit
                    b=bit.bit_length()-1
                    dist[a][b]=nd; unvis[a]^=bit; q.append((a,b))
    for row in dist:
        print(' '.join(str(-1 if x==inf else x) for x in row))
main()

