from typing import List
from functools import lru_cache
import sys
sys.setrecursionlimit(10000)
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order in matrix coordinates: SE, SW, NW, NE.
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        @lru_cache(None)
        def extend(i, j, d, can_turn, expected):
            if not (0 <= i < n and 0 <= j < m) or grid[i][j] != expected:
                return 0
            next_value = 0 if expected == 2 else 2
            di, dj = dirs[d]
            best = extend(i + di, j + dj, d, can_turn, next_value)
            if can_turn:
                nd = (d + 1) % 4
                di, dj = dirs[nd]
                best = max(best, extend(i + di, j + dj, nd, 0, next_value))
            return best + 1

        answer = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    answer = max(answer, 1)
                    for d, (di, dj) in enumerate(dirs):
                        answer = max(answer, 1 + extend(i + di, j + dj, d, 1, 2))
        return answer

