from typing import List
from math import factorial
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        available = odds + evens
        result = []
        expected = None
        for pos in range(n):
            remaining_positions = n - pos - 1
            chosen = None
            for value in sorted(available):
                parity = value % 2
                if expected is not None and parity != expected:
                    continue
                if expected is None and n % 2 == 1 and parity != 1:
                    continue
                odd_left = len(odds) - (parity == 1)
                even_left = len(evens) - (parity == 0)
                next_parity = 1 - parity
                if remaining_positions % 2 == 0:
                    odd_slots = even_slots = remaining_positions // 2
                elif next_parity == 1:
                    odd_slots = remaining_positions // 2 + 1
                    even_slots = remaining_positions // 2
                else:
                    odd_slots = remaining_positions // 2
                    even_slots = remaining_positions // 2 + 1
                if odd_left != odd_slots or even_left != even_slots:
                    continue
                block = factorial(odd_left) * factorial(even_left)
                if k > block:
                    k -= block
                else:
                    chosen = value
                    result.append(value)
                    if parity:
                        odds.remove(value)
                    else:
                        evens.remove(value)
                    available.remove(value)
                    expected = 1 - parity
                    break
            if chosen is None:
                return []
        return result

