class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        full = (1 << k) - 1
        coeff = [((pow(10, n - 1 - i, k) + pow(10, i, k)) % k) for i in range(m)]
        # For an odd-length palindrome, the center digit is counted only once.
        if n % 2:
            i = m - 1
            coeff[i] = pow(10, i, k) % k
        dp = [0] * (m + 1)
        dp[m] = 1
        for i in range(m - 1, -1, -1):
            mask = 0
            for d in range(10):
                s = (d * coeff[i]) % k
                prev = dp[i + 1]
                shifted = ((prev << s) | (prev >> (k - s))) & full if s else prev
                mask |= shifted
            dp[i] = mask
        digits = []
        rem = 0
        for i in range(m):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (rem + d * coeff[i]) % k
                if (dp[i + 1] >> ((-nr) % k)) & 1:
                    digits.append(str(d))
                    rem = nr
                    break
        return ''.join(digits + (digits[:-1] if n % 2 else digits)[::-1])

