class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        n = len(s)
        ans = n
        # For a chosen common frequency k, flow represents characters changed
        # from the preceding letter into this one.
        for k in range(1, max(cnt) + 1):
            inf = 10**9
            dp = [inf] * (n + 1)
            dp[0] = 0
            for c in cnt:
                # For each incoming flow p, choose final count x=0 or k.
                # Any surplus can be deleted or sent onward at equal cost.
                ndp = [inf] * (n + 1)
                pref = [inf] * (n + 2)
                # For x=0 or k, outgoing q can range from zero to surplus.
                # Compute transition by scanning feasible incoming/outgoing pairs.
                for p, val in enumerate(dp):
                    if val == inf:
                        continue
                    a = c + p
                    for x in (0, k):
                        if a >= x:
                            surplus = a - x
                            cost = val + surplus
                            # Emit any amount up to surplus; unused surplus is deleted.
                            for q in range(surplus + 1):
                                if cost < ndp[q]:
                                    ndp[q] = cost
                        else:
                            cost = val + x - a
                            if cost < ndp[0]:
                                ndp[0] = cost
                dp = ndp
            ans = min(ans, min(dp))
        return ans

