import sys

def fwht(a, inv=False):
    n = len(a)
    step = 1
    while step < n:
        jump = step << 1
        for i in range(0, n, jump):
            for j in range(i, i + step):
                x, y = a[j], a[j + step]
                a[j] = x + y
                a[j + step] = x - y
        step = jump
    if inv:
        for i in range(n):
            a[i] //= n


