    data = sys.stdin.buffer.read().split()
    if not data:
        return
    H, W = map(int, data[:2])
    n = 1 << W
    freq = [0] * n
    for row in data[2:2 + H]:
        mask = int(row, 2)
        freq[mask] += 1
    kernel = [min(m.bit_count(), W - m.bit_count()) for m in range(n)]
    fwht(freq)
    fwht(kernel)
    for i in range(n):
        freq[i] *= kernel[i]
    fwht(freq, True)
    print(min(freq))

