from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        oa, ob, oc = occurrences(a), occurrences(b), occurrences(c)
        ans = n + 1
        for start in oa:
            end_a = start + len(a)
            ib = bisect_left(ob, end_a)
            if ib == len(ob):
                continue
            start_b = ob[ib]
            end_b = start_b + len(b)
            ic = bisect_left(oc, end_b)
            if ic == len(oc):
                continue
            end_c = oc[ic] + len(c)
            ans = min(ans, end_c - start)
        return -1 if ans == n + 1 else ans

