import sys,bisect

def solve_case(n,a,b):
    x=[i for i,c in enumerate(a) if c=='1']
    y=[i for i,c in enumerate(b) if c=='1']
    m,k=len(x),len(y)
    if k>m:
        return -1
    def ok(d):
        p=0
        for j,t in enumerate(y):
            L=bisect.bisect_left(x,t-d)
            R=bisect.bisect_right(x,t+d)
            if p<L or p>=R:
                return False
            if j==k-1:
                return x[-1]<=t+d
            next_L=bisect.bisect_left(x,y[j+1]-d)
            q=max(p+1,next_L)
            if q>R or m-q<k-j-1:
                return False
            p=q
        return False
    lo,hi=0,n
    while lo<hi:
        mid=(lo+hi)//2
        if ok(mid):
            hi=mid
        else:
            lo=mid+1
    return lo

